package br.com.guerravpn.crediflow;

import android.app.Activity;
import android.content.ContentResolver;
import android.content.Intent;
import android.content.SharedPreferences;
import android.os.Bundle;
import android.text.InputType;
import android.view.View;
import android.view.Window;
import android.widget.Button;
import android.widget.CheckBox;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ProgressBar;
import android.widget.TextView;
import android.widget.Toast;

import org.json.JSONArray;
import org.json.JSONObject;

import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.security.SecureRandom;
import java.util.Locale;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class MainActivityV06 extends Activity {
    static final int PICK_FRONT=201,PICK_BACK=202,PICK_PAY=203;
    final ExecutorService io=Executors.newFixedThreadPool(4);
    Ui u; SharedPreferences prefs;
    String accessToken,refreshToken,userId,role,email,pendingId,pendingSecret,pendingEmail;

    @Override protected void onCreate(Bundle b){super.onCreate(b);Window w=getWindow();w.setStatusBarColor(Ui.NAVY);w.setNavigationBarColor(Ui.NAVY);u=new Ui(this);prefs=getSharedPreferences("crediflow",MODE_PRIVATE);load();if(accessToken!=null&&!accessToken.isEmpty()){if("admin".equals(role))new AdminUi(this).show();else showHome();}else showWelcome();}
    void load(){accessToken=prefs.getString("access_token",null);refreshToken=prefs.getString("refresh_token",null);userId=prefs.getString("user_id",null);role=prefs.getString("role",null);email=prefs.getString("email",null);pendingId=prefs.getString("pending_id",null);pendingSecret=prefs.getString("pending_secret",null);pendingEmail=prefs.getString("pending_email",null);}
    void saveSession(JSONObject o){accessToken=o.optString("access_token",null);refreshToken=o.optString("refresh_token",null);JSONObject usr=o.optJSONObject("user");if(usr!=null){userId=usr.optString("id",userId);email=usr.optString("email",email);JSONObject m=usr.optJSONObject("app_metadata");role=m==null?"client":m.optString("role","client");}prefs.edit().putString("access_token",accessToken).putString("refresh_token",refreshToken).putString("user_id",userId).putString("role",role).putString("email",email).apply();}
    void logout(){accessToken=refreshToken=userId=role=email=null;prefs.edit().remove("access_token").remove("refresh_token").remove("user_id").remove("role").remove("email").apply();showWelcome();}
    void savePending(String id,String secret,String mail){pendingId=id;pendingSecret=secret;pendingEmail=mail;prefs.edit().putString("pending_id",id).putString("pending_secret",secret).putString("pending_email",mail).apply();}
    void clearPending(){pendingId=pendingSecret=pendingEmail=null;prefs.edit().remove("pending_id").remove("pending_secret").remove("pending_email").apply();}

    void showWelcome(){LinearLayout r=u.page();u.spacer(r,42);u.logo(r);u.spacer(r,34);u.eyebrow(r,"CREDIFLOW");u.title(r,"Crédito simples,\nanálise clara.",38);u.body(r,"Versão 1.0 · build 10");u.spacer(r,20);r.addView(u.primary("Criar cadastro",v->showRegister()));r.addView(u.outline("Entrar na minha conta",v->showLogin()));r.addView(u.outline("Acompanhar solicitação",v->showTracking()));LinearLayout c=u.card();u.cardTitle(c,"Fluxo da conta");u.body(c,"Cadastro → documentos → análise manual → aprovação → código por e-mail → criação de senha.");r.addView(c);u.caption(r,"CrediFlow · 1.0 · Professional");}
    void showTracking(){if(pendingId!=null&&!pendingId.isEmpty()&&pendingSecret!=null&&!pendingSecret.isEmpty()){showStatus();return;}LinearLayout r=u.page();u.back(r,this::showWelcome);u.title(r,"Acompanhar solicitação",30);u.body(r,"Não há uma solicitação salva neste aparelho no momento.");LinearLayout c=u.card();u.cardTitle(c,"Como acompanhar");u.body(c,"Ao enviar um novo cadastro, o CrediFlow salva o acompanhamento neste aparelho e mantém o botão disponível mesmo depois da ativação da conta.");c.addView(u.primary("Criar cadastro",v->showRegister()));c.addView(u.outline("Entrar na minha conta",v->showLogin()));r.addView(c);}

    void showLogin(){LinearLayout r=u.page();u.back(r,this::showWelcome);u.logo(r);u.spacer(r,18);u.title(r,"Entrar",32);u.body(r,"Use o e-mail e a senha da sua conta aprovada.");EditText em=u.input("E-mail",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS),pw=u.input("Senha",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);if(email!=null)em.setText(email);r.addView(em);r.addView(pw);TextView err=u.error();r.addView(err);Button go=u.primary("Entrar",null);r.addView(go);go.setOnClickListener(v->{String e=em.getText().toString().trim().toLowerCase(Locale.ROOT),p=pw.getText().toString();if(e.isEmpty()||p.length()<6){err.setText("Confira e-mail e senha.");return;}busy(go,true,"Entrando...");io.execute(()->{try{Api.Resp x=Api.signIn(e,p);if(!x.ok())throw new Exception(x.errorMessage());JSONObject a=x.object();runOnUiThread(()->{saveSession(a);busy(go,false,"Entrar");if("admin".equals(role))new AdminUi(this).show();else showHome();});}catch(Exception ex){runOnUiThread(()->{busy(go,false,"Entrar");err.setText(friendly(ex));});}});});}

    void showRegister(){LinearLayout r=u.page();u.back(r,this::showWelcome);u.title(r,"Criar cadastro",30);u.body(r,"Preencha seus dados para análise manual. O app não aprova crédito sozinho.");EditText n=u.input("Nome completo",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_WORDS),em=u.input("E-mail",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS),cpf=u.input("CPF · somente números",InputType.TYPE_CLASS_NUMBER),ph=u.input("Celular com DDD",InputType.TYPE_CLASS_PHONE),bd=u.input("Nascimento · AAAA-MM-DD",InputType.TYPE_CLASS_DATETIME),addr=u.input("Rua / endereço",InputType.TYPE_CLASS_TEXT),num=u.input("Número",InputType.TYPE_CLASS_TEXT),comp=u.input("Complemento · opcional",InputType.TYPE_CLASS_TEXT),bairro=u.input("Bairro",InputType.TYPE_CLASS_TEXT),city=u.input("Cidade",InputType.TYPE_CLASS_TEXT),uf=u.input("UF · ex.: RS",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_CHARACTERS),cep=u.input("CEP",InputType.TYPE_CLASS_NUMBER),job=u.input("Profissão / ocupação",InputType.TYPE_CLASS_TEXT),inc=u.input("Renda mensal · ex.: 2500,00",InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);for(EditText e:new EditText[]{n,em,cpf,ph,bd,addr,num,comp,bairro,city,uf,cep,job,inc})r.addView(e);CheckBox ok=u.check("Declaro que os dados são verdadeiros e autorizo o uso para cadastro e análise de crédito.");r.addView(ok);TextView err=u.error();r.addView(err);Button send=u.primary("Enviar cadastro",null);r.addView(send);send.setOnClickListener(v->{if(!ok.isChecked()){err.setText("Confirme a declaração.");return;}String secret=randomSecret();try{JSONObject b=new JSONObject();b.put("p_full_name",n.getText().toString().trim());b.put("p_email",em.getText().toString().trim().toLowerCase(Locale.ROOT));b.put("p_cpf",cpf.getText().toString());b.put("p_phone",ph.getText().toString());b.put("p_birth_date",bd.getText().toString());b.put("p_address_line",addr.getText().toString());b.put("p_address_number",num.getText().toString());b.put("p_address_complement",comp.getText().toString());b.put("p_neighborhood",bairro.getText().toString());b.put("p_city",city.getText().toString());b.put("p_state",uf.getText().toString());b.put("p_postal_code",cep.getText().toString());b.put("p_occupation",job.getText().toString());String iv=inc.getText().toString().trim().replace(',','.');b.put("p_monthly_income",iv.isEmpty()?0:Double.parseDouble(iv));b.put("p_status_secret",secret);busy(send,true,"Enviando...");io.execute(()->{try{Api.Resp x=Api.submitApplication(b);if(!x.ok())throw new Exception(x.errorMessage());JSONArray a=x.array();if(a.length()==0)throw new Exception("Cadastro sem identificação.");String id=a.getJSONObject(0).optString("application_id");runOnUiThread(()->{savePending(id,secret,em.getText().toString().trim().toLowerCase(Locale.ROOT));showStatus();});}catch(Exception ex){runOnUiThread(()->{busy(send,false,"Enviar cadastro");err.setText(friendly(ex));});}});}catch(Exception ex){err.setText("Confira os dados informados.");}});}

    void showStatus(){if(pendingId==null){showTracking();return;}LinearLayout r=u.page();u.back(r,this::showWelcome);u.title(r,"Acompanhar solicitação",30);u.body(r,pendingEmail==null?"":pendingEmail);LinearLayout box=u.card();ProgressBar p=new ProgressBar(this);box.addView(p);r.addView(box);TextView err=u.error();r.addView(err);r.addView(u.outline("Atualizar análise",v->showStatus()));LinearLayout docs=u.card();u.cardTitle(docs,"Documentos");u.body(docs,"Envie frente e verso da identidade e um comprovante de renda.");docs.addView(u.outline("Documento · frente",v->pick(PICK_FRONT,"image/*")));docs.addView(u.outline("Documento · verso",v->pick(PICK_BACK,"image/*")));docs.addView(u.outline("Comprovante de renda",v->pick(PICK_PAY,"*/*")));r.addView(docs);io.execute(()->{try{Api.Resp x=Api.checkApplication(pendingId,pendingSecret);if(!x.ok())throw new Exception(x.errorMessage());JSONArray a=x.array();if(a.length()==0)throw new Exception("Cadastro não encontrado.");JSONObject s=a.getJSONObject(0);runOnUiThread(()->renderStatus(box,p,s));}catch(Exception ex){runOnUiThread(()->{p.setVisibility(View.GONE);err.setText(friendly(ex));});}});}
    void renderStatus(LinearLayout b,ProgressBar p,JSONObject s){p.setVisibility(View.GONE);String st=s.optString("application_status","under_review");b.addView(u.badge(statusPt(st),statusColor(st)));if(!s.isNull("approved_limit"))u.stat(b,"Limite aprovado",money(s.optDouble("approved_limit",0)));int score=s.optInt("verification_score",-1);if(score>=0)u.stat(b,"Verificação",score+"/100 · "+s.optString("verification_level",""));String note=s.optString("correction_note","");if(!note.isEmpty())u.body(b,"Orientação do Admin: "+note);JSONObject d=s.optJSONObject("document_status");if(d!=null)u.caption(b,"Frente: "+d.optString("identity_front","pendente")+" · Verso: "+d.optString("identity_back","pendente")+" · Renda: "+d.optString("payslip","pendente"));if(s.optBoolean("activation_ready",false)||"activation_sent".equals(st))b.addView(u.primary("Inserir código recebido por e-mail",v->showActivation()));else if("approved".equals(st))u.body(b,"Aguarde o Admin enviar o código de ativação por e-mail.");}

    void showActivation(){LinearLayout r=u.page();u.back(r,this::showStatus);u.title(r,"Ativar conta",30);u.body(r,"Digite o código recebido por e-mail.");EditText code=u.input("Código de ativação",InputType.TYPE_CLASS_NUMBER);r.addView(code);TextView err=u.error();r.addView(err);Button go=u.primary("Verificar código",null);r.addView(go);go.setOnClickListener(v->{String c=code.getText().toString().trim();if(c.length()<6){err.setText("Digite o código completo.");return;}busy(go,true,"Verificando...");io.execute(()->{try{Api.Resp x=Api.verifyEmailOtp(pendingEmail,c);if(!x.ok())throw new Exception(x.errorMessage());JSONObject a=x.object();runOnUiThread(()->{saveSession(a);showPassword();});}catch(Exception ex){runOnUiThread(()->{busy(go,false,"Verificar código");err.setText(friendly(ex));});}});});}
    void showPassword(){LinearLayout r=u.page();u.title(r,"Criar senha",30);u.body(r,"Defina sua senha para os próximos acessos.");EditText a=u.input("Nova senha",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD),b=u.input("Confirmar senha",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);r.addView(a);r.addView(b);TextView err=u.error();r.addView(err);Button go=u.primary("Criar senha e entrar",null);r.addView(go);go.setOnClickListener(v->{String p=a.getText().toString();if(p.length()<8||!p.equals(b.getText().toString())){err.setText("Use 8+ caracteres e confirme a mesma senha.");return;}busy(go,true,"Salvando...");io.execute(()->{try{Api.Resp x=Api.updatePassword(accessToken,p);if(!x.ok())throw new Exception(x.errorMessage());x=Api.completeActivation(accessToken);if(!x.ok())throw new Exception(x.errorMessage());runOnUiThread(this::showHome);}catch(Exception ex){runOnUiThread(()->{busy(go,false,"Criar senha e entrar");err.setText(friendly(ex));});}});});}

    void showHome(){LinearLayout r=u.page();u.logo(r);u.spacer(r,18);TextView title=u.title(r,"Minha conta",30),sub=u.body(r,"Carregando seus dados...");LinearLayout box=u.card();ProgressBar p=new ProgressBar(this);box.addView(p);r.addView(box);r.addView(u.primary("Solicitar empréstimo",v->new LoanUi(this).show()));r.addView(u.outline("Meu perfil",v->showProfile()));r.addView(u.outline("Sair",v->logout()));io.execute(()->{try{Api.Resp pr=Api.get("/rest/v1/profiles?select=full_name,display_name,email,phone,cpf_last4,account_status&user_id=eq."+userId+"&limit=1",accessToken),lr=Api.get("/rest/v1/credit_limits?select=limit_amount,risk_tier,monthly_rate,max_installments,late_interest_daily_rate,late_fee_rate&user_id=eq."+userId+"&active=eq.true&limit=1",accessToken),lo=Api.get("/rest/v1/loans?select=id,principal,total_amount,installments_count,status,requested_at,first_due_date&user_id=eq."+userId+"&order=requested_at.desc",accessToken);if(!pr.ok())throw new Exception(pr.errorMessage());if(!lr.ok())throw new Exception(lr.errorMessage());if(!lo.ok())throw new Exception(lo.errorMessage());JSONArray pa=pr.array(),la=lr.array(),loa=lo.array();JSONObject prof=pa.length()>0?pa.getJSONObject(0):new JSONObject(),lim=la.length()>0?la.getJSONObject(0):new JSONObject();runOnUiThread(()->{p.setVisibility(View.GONE);String name=prof.optString("display_name",prof.optString("full_name","Cliente"));title.setText("Olá, "+firstName(name));sub.setText("Sua conta CrediFlow");double approved=lim.optDouble("limit_amount",0),used=0;for(int i=0;i<loa.length();i++){JSONObject l=loa.optJSONObject(i);if(l==null)continue;String st=l.optString("status");if("requested".equals(st)||"approved".equals(st)||"disbursing".equals(st)||"active".equals(st)||"late".equals(st))used+=l.optDouble("principal",0);}u.eyebrow(box,"LIMITE DISPONÍVEL");u.title(box,money(Math.max(0,approved-used)),34);u.body(box,"Limite aprovado "+money(approved)+" · taxa "+percent(lim.optDouble("monthly_rate",0))+" a.m. · até "+lim.optInt("max_installments",1)+"x");u.caption(box,"Atraso: "+percent(lim.optDouble("late_interest_daily_rate",0))+" ao dia · multa "+percent(lim.optDouble("late_fee_rate",0)));u.cardTitle(box,"Empréstimos");if(loa.length()==0)u.body(box,"Nenhum empréstimo ainda.");for(int i=0;i<loa.length();i++){JSONObject l=loa.optJSONObject(i);if(l==null)continue;LinearLayout c=u.mini();u.cardTitle(c,money(l.optDouble("principal",0))+" · "+l.optInt("installments_count",1)+"x");u.body(c,"Total "+money(l.optDouble("total_amount",0))+" · "+statusPt(l.optString("status")));String fd=l.optString("first_due_date","");if(!fd.isEmpty())u.caption(c,"1º vencimento: "+fd);box.addView(c);}});}catch(Exception ex){runOnUiThread(()->{p.setVisibility(View.GONE);sub.setText(friendly(ex));});}});}

    void showProfile(){LinearLayout r=u.page();u.back(r,this::showHome);u.title(r,"Meu perfil",30);LinearLayout box=u.card();ProgressBar p=new ProgressBar(this);box.addView(p);r.addView(box);r.addView(u.outline("Sair da conta",v->logout()));io.execute(()->{try{Api.Resp x=Api.get("/rest/v1/profiles?select=full_name,display_name,email,phone,cpf_last4,account_status&user_id=eq."+userId+"&limit=1",accessToken);if(!x.ok())throw new Exception(x.errorMessage());JSONArray a=x.array();JSONObject q=a.length()>0?a.getJSONObject(0):new JSONObject();runOnUiThread(()->{p.setVisibility(View.GONE);u.stat(box,"Nome",q.optString("display_name",q.optString("full_name","-")));u.stat(box,"E-mail",q.optString("email",email));u.stat(box,"Celular",q.optString("phone","-"));u.stat(box,"CPF","•••.•••.•••-"+q.optString("cpf_last4","----"));u.stat(box,"Conta",q.optString("account_status","active"));});}catch(Exception ex){runOnUiThread(()->{p.setVisibility(View.GONE);u.body(box,friendly(ex));});}});}

    void pick(int code,String type){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(type);if(code==PICK_PAY)i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/pdf","image/jpeg","image/png","image/webp"});startActivityForResult(i,code);}
    @Override protected void onActivityResult(int rc,int result,Intent data){super.onActivityResult(rc,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;if(rc!=PICK_FRONT&&rc!=PICK_BACK&&rc!=PICK_PAY)return;String kind=rc==PICK_FRONT?"identity_front":rc==PICK_BACK?"identity_back":"payslip";Toast.makeText(this,"Enviando documento...",Toast.LENGTH_SHORT).show();io.execute(()->{try{ContentResolver cr=getContentResolver();String mime=cr.getType(data.getData());if(mime==null)mime="application/octet-stream";byte[] bytes=read(data.getData());Api.Resp x=Api.uploadApplicationDocument(pendingId,pendingSecret,kind,mime,bytes);if(!x.ok())throw new Exception(x.errorMessage());runOnUiThread(()->{Toast.makeText(this,"Documento enviado.",Toast.LENGTH_SHORT).show();showStatus();});}catch(Exception ex){runOnUiThread(()->Toast.makeText(this,friendly(ex),Toast.LENGTH_LONG).show());}});}
    byte[] read(android.net.Uri uri)throws Exception{try(InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new Exception("Arquivo inválido.");byte[] b=new byte[8192];int n,total=0;while((n=in.read(b))!=-1){total+=n;if(total>10*1024*1024)throw new Exception("Arquivo maior que 10 MB.");out.write(b,0,n);}return out.toByteArray();}}

    void busy(Button b,boolean x,String t){b.setEnabled(!x);b.setAlpha(x?.65f:1f);b.setText(t);}String randomSecret(){byte[] b=new byte[32];new SecureRandom().nextBytes(b);StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format(Locale.US,"%02x",x));return s.toString();}
    static String money(double v){return String.format(new Locale("pt","BR"),"R$ %,.2f",v);}static String percent(double v){return String.format(new Locale("pt","BR"),"%.2f%%",v*100);}static String firstName(String x){if(x==null||x.trim().isEmpty())return"Cliente";return x.trim().split("\\s+")[0];}
    static String statusPt(String s){if(s==null)return"-";switch(s){case"under_review":return"Em análise";case"approved":return"Aprovado";case"activation_sent":return"Ativação enviada";case"active":return"Ativo";case"requested":return"Solicitado";case"disbursing":return"Liberando";case"late":return"Atrasado";case"rejected":return"Rejeitado";case"correction_required":return"Correção necessária";case"paid":return"Pago";default:return s.replace('_',' ');}}static int statusColor(String s){if("approved".equals(s)||"active".equals(s)||"paid".equals(s))return Ui.GREEN;if("rejected".equals(s)||"cancelled".equals(s)||"late".equals(s))return Ui.RED;return Ui.AMBER;}
    static String friendly(Exception e){String m=e.getMessage();if(m==null||m.isEmpty())return"Não foi possível concluir. Tente novamente.";if(m.contains("Invalid login credentials"))return"E-mail ou senha incorretos.";if(m.contains("amount_exceeds_available_limit"))return"O valor ultrapassa o limite disponível.";if(m.contains("required_documents_missing"))return"Faltam documentos obrigatórios.";if(m.contains("application_already_exists"))return"Já existe um cadastro para esses dados.";if(m.contains("application_closed"))return"Este cadastro está encerrado e não pode mais ser alterado por essa análise.";if(m.contains("application_already_provisioned"))return"A conta já foi criada. Para alterar as condições, use Atualizar condições.";if(m.contains("first_due_date_in_past"))return"A primeira parcela não pode estar no passado.";if(m.contains("first_due_date_too_far"))return"A primeira parcela não pode passar de 1 mês a partir de hoje.";if(m.contains("invalid_first_due_date"))return"Escolha uma data válida para a primeira parcela.";return m;}
    @Override public void onBackPressed(){showWelcome();}@Override protected void onDestroy(){io.shutdownNow();super.onDestroy();}
}
